/* icons-2.js — official tool logos embedded as data URIs (4 of 18).
   Generated 2026-10-05. Base64 text is used because the GitHub file API
   wrapper cannot transport binary PNGs; the browser decodes them natively.
   Add new icons via Object.assign(window.ICONS, {"slug": "data:image/png;base64,..."}). */
window.ICONS = window.ICONS || {};
Object.assign(window.ICONS, {
"github": "data:image/png;base64,",
"notebooklm": "data:image/png;base64,",
"gamma": "data:image/png;base64,",
"linkedin": "data:image/png;base64,",
});